// Package api_contract is the WO-040 backward-compatibility regression
// suite: it exercises the endpoint contract captured in
// tests/fixtures/api_contract_snapshot.json (generated by
// tools/generate_api_snapshot from http/handler.go) against a live 3-node
// Vault test cluster, so a future handler-registry or module-boundary
// change that removes an endpoint, changes its methods, or breaks the
// forwarding/DoS-limit contract fails CI instead of shipping silently.
//
// This suite deliberately does not use a package-level TestMain to
// bootstrap the cluster: vault.NewTestCluster requires a *testing.T (or
// testing.TB), which TestMain's *testing.M cannot supply. No other test in
// vault/external_tests uses TestMain for this reason - each spins up its
// own cluster instead. TestAPIContract follows that convention: it builds
// one 3-node cluster and shares it across every AC-mapped scenario via
// t.Run subtests, per the WO's own constraint to use "shared cluster setup"
// for the multi-scenario suite while keeping subtests independently
// reportable (`go test -run TestAPIContract/InjectDataRoutes`, etc.).
package api_contract

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"testing"
	"time"

	log "github.com/hashicorp/go-hclog"
	gplugin "github.com/hashicorp/go-plugin"
	"github.com/hashicorp/vault/api"
	"github.com/hashicorp/vault/helper/testhelpers"
	vaulthttp "github.com/hashicorp/vault/http"
	"github.com/hashicorp/vault/sdk/helper/logging"
	"github.com/hashicorp/vault/sdk/logical"
	"github.com/hashicorp/vault/sdk/plugin"
	"github.com/hashicorp/vault/sdk/plugin/mock"
	"github.com/hashicorp/vault/vault"
	"github.com/stretchr/testify/require"
)

// snapshotEndpoint mirrors one entry of tests/fixtures/api_contract_snapshot.json's
// "endpoints" array. Only the fields this suite asserts against are
// declared; encoding/json ignores the rest.
type snapshotEndpoint struct {
	Path                 string   `json:"path"`
	Methods              []string `json:"methods"`
	AuthRequired         bool     `json:"auth_required"`
	FIPSSensitive        bool     `json:"fips_sensitive"`
	ForwardingBehavior   string   `json:"forwarding_behavior"`
	Category             string   `json:"category"`
	ConditionalOnSetting string   `json:"conditional_on_setting"`
}

type jsonDoSLimits struct {
	DefaultMaxRequestSize          int64 `json:"default_max_request_size"`
	DefaultMaxTokenHeaderSize      int64 `json:"default_max_token_header_size"`
	CustomMaxJSONDepth             int64 `json:"custom_max_json_depth"`
	CustomMaxJSONStringValueLength int64 `json:"custom_max_json_string_value_length"`
	CustomMaxJSONObjectEntryCount  int64 `json:"custom_max_json_object_entry_count"`
	CustomMaxJSONArrayElementCount int64 `json:"custom_max_json_array_element_count"`
	CustomMaxJSONToken             int64 `json:"custom_max_json_token"`
}

type forwardingPaths struct {
	AlwaysRedirect          []string            `json:"always_redirect"`
	PerMethodAlwaysRedirect map[string][]string `json:"per_method_always_redirect"`
}

type contractSnapshot struct {
	EndpointCount   int                `json:"endpoint_count"`
	JSONDoSLimits   jsonDoSLimits      `json:"json_dos_limits"`
	ForwardingPaths forwardingPaths    `json:"forwarding_paths"`
	Endpoints       []snapshotEndpoint `json:"endpoints"`
}

// goldenFilePath locates tests/fixtures/api_contract_snapshot.json relative
// to this source file, so the test works regardless of the working
// directory `go test` is invoked from.
func goldenFilePath(t testing.TB) string {
	_, thisFile, _, ok := runtime.Caller(0)
	require.True(t, ok, "runtime.Caller failed to resolve this test file's path")
	repoRoot := filepath.Join(filepath.Dir(thisFile), "..", "..", "..")
	return filepath.Join(repoRoot, "tests", "fixtures", "api_contract_snapshot.json")
}

func loadSnapshot(t testing.TB) *contractSnapshot {
	path := goldenFilePath(t)
	data, err := os.ReadFile(path)
	require.NoError(t, err, "golden file missing - run `make api-snapshot` (or `go run ./tools/generate_api_snapshot`) to regenerate %s", path)

	var snap contractSnapshot
	require.NoError(t, json.Unmarshal(data, &snap), "golden file %s is not valid JSON", path)
	require.NotEmpty(t, snap.Endpoints, "golden file %s declares no endpoints", path)
	return &snap
}

// dedupeByPath keeps the first-seen entry per Path. Several source
// registration sites in http/handler.go register the *same* path under
// mutually exclusive runtime conditions (e.g. sys/metrics is registered
// once for unauthenticated listener config and once for authenticated
// default config - see conditional_on_setting in the golden file), so the
// snapshot legitimately contains duplicate paths with different metadata.
// Existence/JSON-shape checks only need one representative per path.
func dedupeByPath(endpoints []snapshotEndpoint) []snapshotEndpoint {
	seen := make(map[string]bool, len(endpoints))
	out := make([]snapshotEndpoint, 0, len(endpoints))
	for _, e := range endpoints {
		if seen[e.Path] {
			continue
		}
		seen[e.Path] = true
		out = append(out, e)
	}
	return out
}

// noTokenClient returns a clone of client with its token cleared, for
// exercising the AuthRequired=false vs. AuthRequired=true contract.
func noTokenClient(t testing.TB, client *api.Client) *api.Client {
	clone, err := client.Clone()
	require.NoError(t, err)
	clone.SetToken("")
	return clone
}

// TestAPIContract is WO-040's integration suite: a single 3-node cluster
// (per the WO's constraint to keep total run time under 10 minutes via
// shared cluster setup) shared across every AC-mapped scenario.
func TestAPIContract(t *testing.T) {
	snap := loadSnapshot(t)

	cluster := vault.NewTestCluster(t, &vault.CoreConfig{}, &vault.TestClusterOptions{
		HandlerFunc: vaulthttp.Handler,
		NumCores:    3,
	})
	defer cluster.Cleanup()
	testhelpers.WaitForActiveNode(t, cluster)

	client := cluster.Cores[0].Client
	// vault.NewTestCluster's default apiClient errors out on any redirect
	// ("redirects not allowed in these tests" - see vault/testing.go). A
	// few catch-all/collection paths (/v1/, /v1/sys/, /v1/sys/audit-hash/,
	// /v1/sys/config/state/, /v1/sys/pprof/) issue an internal redirect
	// when queried at their bare root, so every subtest below needs the
	// api package's normal, sane default of returning the raw response
	// instead of following or erroring on a redirect.
	client.SetCheckRedirect(func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	})
	unauth := noTokenClient(t, client)

	t.Run("AllEndpointsExist", func(t *testing.T) {
		testAllEndpointsExist(t, client, unauth, snap)
	})
	t.Run("InjectDataRoutes", func(t *testing.T) {
		testInjectDataRoutes(t, client, snap)
	})
	t.Run("ForwardingPaths", func(t *testing.T) {
		testForwardingPaths(t, cluster, snap)
	})
	t.Run("PluginGRPCContract", func(t *testing.T) {
		testPluginGRPCContract(t)
	})
	t.Run("RouterMountContract", func(t *testing.T) {
		testRouterMountContract(t, client)
	})
	t.Run("JSONLimits", func(t *testing.T) {
		testJSONLimits(t, client, snap)
	})
}

// dangerousToProbeWithRootAuth lists endpoints where issuing even a
// parameter-less, root-authenticated request performs a real, irreversible
// side effect against the shared test cluster (sealing it, stepping down
// the active node, attempting a raft bootstrap/join) rather than safely
// erroring - discovered empirically while writing this suite: an early
// version authenticated-probed every endpoint uniformly, and the resulting
// mid-run seal of the cluster cascaded into unrelated failures (503s) for
// every endpoint tested afterward. AC1's existence check for these paths
// relies solely on the unauthenticated probe below, which never reaches
// the operation (CheckToken rejects it first) and so cannot trigger it.
var dangerousToProbeWithRootAuth = map[string]bool{
	"/v1/sys/seal":                      true,
	"/v1/sys/unseal":                    true,
	"/v1/sys/step-down":                 true,
	"/v1/sys/storage/raft/bootstrap":    true,
	"/v1/sys/storage/raft/join":         true,
	"/v1/sys/rekey/init":                true,
	"/v1/sys/rekey/update":              true,
	"/v1/sys/rekey/verify":              true,
	"/v1/sys/rekey-recovery-key/init":   true,
	"/v1/sys/rekey-recovery-key/update": true,
	"/v1/sys/rekey-recovery-key/verify": true,
	"/v1/sys/generate-root/attempt":     true,
	"/v1/sys/generate-root/update":      true,
}

// bareCollectionRootsWithNo404Leaf lists catch-all/collection paths that
// are only meaningful with a sub-resource appended (e.g.
// "/v1/sys/config/state/sanitized", not the bare "/v1/sys/config/state/"
// collection root itself). GET-ing the bare root reaches the real backend
// (proving routing works, same as audit-hash/ in testInjectDataRoutes) and
// the backend correctly answers "unsupported path" with a 404 - that is
// the logical layer's 404, not the mux's, and is expected here rather than
// evidence of a missing registration.
var bareCollectionRootsWithNo404Leaf = map[string]bool{
	"/v1/":                  true,
	"/v1/sys/":              true,
	"/v1/sys/audit-hash/":   true,
	"/v1/sys/config/state/": true,
}

// noAuthEnforcementFinding documents a real gap this suite discovered:
// handleSysRaftBootstrap and handleSysRaftJoin (http/sys_raft.go) call
// straight into core.RaftBootstrap/core.RaftJoin without ever calling
// CheckToken, unlike every generic-pipeline endpoint (handleLogical /
// handleRequestForwarding, which do enforce auth before dispatch). The
// HandlerRegistry entries for both paths declare AuthRequired: true
// (http/handler.go), but that field is registry metadata describing
// intent - it does not, by itself, wrap the handler in an auth check the
// way it does for the generic logical dispatch handlers. An
// unauthenticated request to either path reaches core.RaftBootstrap /
// core.RaftJoin directly; in this suite it surfaces as 500 only because
// the test cluster's storage backend isn't raft, not because auth was
// enforced. This is exactly the class of "config-layer handler bypasses
// the HandleRequest -> CheckToken pipeline" trust-boundary violation this
// epic is about (see the architecture artifact's Trust Boundary Map,
// boundary 2) - flagged here as a finding for a follow-up security fix,
// not fixed in this WO (out of scope: this story only builds the
// regression detection harness).
var noAuthEnforcementFinding = map[string]bool{
	"/v1/sys/storage/raft/bootstrap": true,
	"/v1/sys/storage/raft/join":      true,
}

// testAllEndpointsExist implements AC1 / implementation_steps #3: for every
// endpoint declared in the golden file, issue a request via the api.Client
// and assert the endpoint exists (i.e. the mux actually routes it -
// asserting not-404). For endpoints declaring AuthRequired=true, the same
// check is repeated unauthenticated, asserting a 400/401/403 rejection
// rather than a silent success or a 404 (which would mean the path itself
// vanished, not that auth was enforced).
//
// A 405 (method not allowed) is treated as a routed-but-method-mismatched
// response, not a failure: the golden file's Methods field records what
// http/handler.go declares as accepted at the HTTP/mux layer (per AC2),
// which for the injectDataIntoTopRoutes batch is a single shared list
// applied to all ~22 paths; several of those paths (capabilities*,
// remount, rotate) don't actually implement a read (GET) operation at the
// logical-backend layer and correctly 405 there instead. 405 is one of
// AC1's own enumerated expected status codes.
//
// Recovery-mode endpoints (category "recovery_mode": /v1/sys/raw/,
// /v1/sys/generate-recovery-token/*) and UI endpoints (category "ui": /,
// /ui, /ui/, /robots.txt) are excluded. Recovery mode is a distinct server
// mode (-recovery flag) vault.NewTestCluster does not model (edge_case 2).
// UI routes require core.UIEnabled(), which vault.NewTestCluster's default
// CoreConfig leaves off, and serving real built UI assets is out of scope
// for an HTTP-contract regression suite. Both are documented verification
// gaps, not skipped assertions on a reachable endpoint.
func testAllEndpointsExist(t *testing.T, client, unauth *api.Client, snap *contractSnapshot) {
	for _, ep := range dedupeByPath(snap.Endpoints) {
		ep := ep
		if ep.Category == "recovery_mode" || ep.Category == "ui" {
			continue
		}
		t.Run(pathTestName(ep.Path), func(t *testing.T) {
			method := representativeMethod(ep.Methods)

			if !dangerousToProbeWithRootAuth[ep.Path] {
				req := client.NewRequest(method, ep.Path)
				if ep.Path == "/v1/sys/pprof/profile" {
					req.Params = url.Values{"seconds": {"1"}} // default profile duration is 30s; keep the suite fast
				}
				resp, err := client.RawRequestWithContext(context.Background(), req)
				status := statusFromResponseOrError(t, resp, err)
				if !bareCollectionRootsWithNo404Leaf[ep.Path] {
					require.NotEqual(t, http.StatusNotFound, status,
						"authenticated %s %s must be routed (registered), got 404", method, ep.Path)
				}
			}

			if !ep.AuthRequired {
				return
			}
			reqNoAuth := unauth.NewRequest(method, ep.Path)
			respNoAuth, errNoAuth := unauth.RawRequestWithContext(context.Background(), reqNoAuth)
			noAuthStatus := statusFromResponseOrError(t, respNoAuth, errNoAuth)
			require.NotEqual(t, http.StatusNotFound, noAuthStatus,
				"unauthenticated %s %s must still be routed (404 would mean the path itself vanished, not an auth rejection)", method, ep.Path)
			if noAuthEnforcementFinding[ep.Path] {
				require.Equal(t, http.StatusInternalServerError, noAuthStatus,
					"documented finding: %s %s bypasses CheckToken entirely (see noAuthEnforcementFinding doc comment) - expected the raft-not-configured 500, got %d", method, ep.Path, noAuthStatus)
				return
			}
			require.Contains(t, []int{http.StatusBadRequest, http.StatusUnauthorized, http.StatusForbidden}, noAuthStatus,
				"AuthRequired=true endpoint %s %s must reject an unauthenticated request with 400/401/403, got %d", method, ep.Path, noAuthStatus)
		})
	}
}

// testInjectDataRoutes implements AC3 / implementation_steps #4: every
// injectDataIntoTopRoutes entry must be routed through
// handleRequestForwarding+handleLogicalWithInjector (golden file
// forwarding_behavior "forwarded") and return a well-formed JSON response,
// proving the data-injection batch is intact.
func testInjectDataRoutes(t *testing.T, client *api.Client, snap *contractSnapshot) {
	var injectRoutes []snapshotEndpoint
	for _, ep := range dedupeByPath(snap.Endpoints) {
		if ep.Category == "inject_data_top_route" {
			injectRoutes = append(injectRoutes, ep)
		}
	}
	require.GreaterOrEqual(t, len(injectRoutes), 20, "expected at least 20 injectDataIntoTopRoutes entries in the golden file (edge_cases/AC3), got %d", len(injectRoutes))

	// audit-hash/ requires a specific mount sub-path
	// ("/v1/sys/audit-hash/<mount>") to hash input against - a GET on the
	// bare collection root has no mount to act on, so a 404 here is the
	// backend correctly rejecting an incomplete request, not evidence of a
	// missing registration. Every other inject-route collection path
	// (audit/, auth/, mounts/, policy/, etc.) supports a bare LIST/GET, so
	// this is a documented, narrow exception rather than a relaxed check.
	pathsWhereNotFoundIsExpected := map[string]bool{
		"/v1/sys/audit-hash/": true,
	}

	for _, ep := range injectRoutes {
		ep := ep
		t.Run(pathTestName(ep.Path), func(t *testing.T) {
			require.Equal(t, "forwarded", ep.ForwardingBehavior,
				"injectDataIntoTopRoutes entry %s must be wrapped in handleRequestForwarding", ep.Path)

			req := client.NewRequest(http.MethodGet, ep.Path)
			resp, err := client.RawRequestWithContext(context.Background(), req)
			// A logical 4xx (e.g. "no backup exists") is an acceptable
			// response shape for this check - what matters is that the
			// route exists and responds with real JSON, not a raw 404/500
			// from a broken registration.
			if err != nil {
				respErr, ok := err.(*api.ResponseError)
				require.True(t, ok, "GET %s: unexpected transport error: %v", ep.Path, err)
				resp = &api.Response{Response: &http.Response{StatusCode: respErr.StatusCode, Header: http.Header{"Content-Type": []string{"application/json"}}}}
			}
			if !pathsWhereNotFoundIsExpected[ep.Path] {
				require.NotEqual(t, http.StatusNotFound, resp.StatusCode, "GET %s must be routed", ep.Path)
			}
			ct := resp.Header.Get("Content-Type")
			require.True(t, strings.Contains(ct, "application/json") || ct == "",
				"GET %s must respond with a JSON content type, got %q", ep.Path, ct)
		})
	}
}

// testForwardingPaths implements AC4 / implementation_steps #5.
//
// AC4's expectation is that alwaysRedirectPaths/perMethodAlwaysRedirectPaths
// force a 307 redirect (respondStandby) on a standby node instead of
// transparent forwarding. Empirically, and confirmed by reading the code
// path, they do not:
//
//   - forwardRequest (http/handler.go) computes
//     `path := trimPath(ns, r.URL.Path)` and then `redirectPath(r.Method, path)`.
//   - trimPath calls namespace.Namespace.TrimmedPath, which only strips the
//     *namespace* prefix (internalshared/namespace/namespace.go:52-54) - for
//     the root namespace that's "", so path still starts with "/v1/".
//   - alwaysRedirectPaths/perMethodAlwaysRedirectPaths are populated (in
//     init(), and in the perMethodRedirectRawPaths var) with entries like
//     "sys/storage/raft/snapshot" - no "/v1/" prefix.
//   - pathmanager.PathManager.HasPath does a radix-tree LongestPrefix
//     lookup (sdk/helper/pathmanager/pathmanager.go:107-119): it matches
//     only if a *registered* entry is a prefix of the queried path. Since
//     "sys/storage/raft/snapshot" is not a prefix of
//     "/v1/sys/storage/raft/snapshot" (they differ at the first byte),
//     HasPath always returns false for real, "/v1/"-prefixed requests.
//
// The subtests below confirm this directly: a standby node forwards (not
// redirects) requests to both an alwaysRedirectPaths entry and an ordinary
// path identically, and a raft-snapshot request gets the *same* status
// from both the active and standby node - proof the standby proxied the
// request rather than serving a local 307. This is recorded as the current,
// real baseline per testing_strategy ("establish a passing baseline on the
// current codebase"), and flagged here as a likely latent defect in
// http/handler.go's trimPath/redirectPath interaction predating this WO.
// Fixing it is out of scope: this story "does not implement the handler
// registry itself or fix any existing layer violations - it only builds
// the regression detection harness" (WO-040 description).
func testForwardingPaths(t *testing.T, cluster *vault.TestCluster, snap *contractSnapshot) {
	require.NotEmpty(t, snap.ForwardingPaths.AlwaysRedirect, "golden file must record alwaysRedirectPaths")
	require.NotEmpty(t, snap.ForwardingPaths.PerMethodAlwaysRedirect, "golden file must record perMethodAlwaysRedirectPaths")

	standbys := testhelpers.DeriveStandbyCores(t, cluster)
	require.NotEmpty(t, standbys, "3-node cluster must have at least one standby")
	standbyClient, err := standbys[0].Client.Clone()
	require.NoError(t, err)
	// Client.Clone() does not copy the token unless config.CloneToken is
	// set, so it must be reapplied explicitly - these requests need root
	// auth to reach the point in handleRequestForwarding where the
	// redirect/forward decision is made.
	standbyClient.SetToken(cluster.RootToken)
	// vault.NewTestCluster's default apiClient errors out on any redirect
	// ("redirects not allowed in these tests" - see vault/testing.go) so
	// accidental redirects fail loudly in tests that don't expect one. This
	// test's entire point is inspecting a real redirect if one occurs, so
	// it opts back into the api package's normal, sane default of
	// returning the raw response instead of following or erroring on it.
	standbyClient.SetCheckRedirect(func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	})
	activeClient := cluster.Cores[0].Client

	t.Run("always_redirect_path_is_forwarded_not_redirected", func(t *testing.T) {
		for _, p := range snap.ForwardingPaths.AlwaysRedirect {
			activeReq := activeClient.NewRequest(http.MethodGet, "/v1/"+p)
			activeResp, activeErr := activeClient.RawRequestWithContext(context.Background(), activeReq)
			activeStatus := statusFromResponseOrError(t, activeResp, activeErr)

			standbyReq := standbyClient.NewRequest(http.MethodGet, "/v1/"+p)
			standbyResp, standbyErr := standbyClient.RawRequestWithContext(context.Background(), standbyReq)
			standbyStatus := statusFromResponseOrError(t, standbyResp, standbyErr)

			require.NotEqual(t, http.StatusTemporaryRedirect, standbyStatus,
				"documented finding: /v1/%s is in alwaysRedirectPaths but the standby did not redirect (see testForwardingPaths doc comment for why)", p)
			require.Equal(t, activeStatus, standbyStatus,
				"standby GET /v1/%s should be transparently forwarded, so its status should match the active node's own response (active=%d standby=%d)", p, activeStatus, standbyStatus)
		}
	})

	t.Run("per_method_always_redirect_is_forwarded_not_redirected", func(t *testing.T) {
		for method, paths := range snap.ForwardingPaths.PerMethodAlwaysRedirect {
			for _, p := range paths {
				standbyReq := standbyClient.NewRequest(method, "/v1/"+p)
				standbyReq.BodyBytes = []byte(`{}`)
				standbyResp, standbyErr := standbyClient.RawRequestWithContext(context.Background(), standbyReq)
				standbyStatus := statusFromResponseOrError(t, standbyResp, standbyErr)
				require.NotEqual(t, http.StatusTemporaryRedirect, standbyStatus,
					"documented finding: standby %s /v1/%s is in perMethodAlwaysRedirectPaths but did not redirect (see testForwardingPaths doc comment for why)", method, p)
			}
		}
	})

	t.Run("ordinary_forwarded_path_is_not_redirected", func(t *testing.T) {
		// sys/mounts is an injectDataIntoTopRoutes entry: forwarded, but
		// NOT in alwaysRedirectPaths, so it must be transparently proxied
		// to the active node rather than redirected.
		req := standbyClient.NewRequest(http.MethodGet, "/v1/sys/mounts")
		resp, err := standbyClient.RawRequestWithContext(context.Background(), req)
		status := statusFromResponseOrError(t, resp, err)
		require.NotEqual(t, http.StatusTemporaryRedirect, status,
			"standby GET /v1/sys/mounts must be forwarded (proxied), not redirected - got 307 with Location %q", resp.Header.Get("Location"))
		require.Equal(t, http.StatusOK, status, "forwarded GET /v1/sys/mounts should succeed via active-node proxy, got %d", status)
	})
}

// testPluginGRPCContract implements AC5 / implementation_steps #6: dispense
// a mock backend plugin over a real in-process gRPC connection (via the
// same exported sdk/plugin.GRPCBackendPlugin + go-plugin test harness an
// external plugin author would use) and exercise every BackendServer
// contract method: Setup, HandleRequest, SpecialPaths, HandleExistenceCheck,
// Initialize, InvalidateKey, Cleanup, Type.
//
// sdk/plugin/grpc_backend_test.go already round-trips HandleRequest,
// SpecialPaths, HandleExistenceCheck, Cleanup, InvalidateKey, Setup, and
// Initialize from *inside* package plugin. This test adds the one
// method that suite doesn't name explicitly (Type) and, more importantly,
// proves the same contract holds from *outside* the package using only
// exported symbols - which is what "backward compatible for external
// plugin consumers" (this WO's description) actually means.
func testPluginGRPCContract(t *testing.T) {
	pluginMap := map[string]gplugin.Plugin{
		plugin.BackendPluginName: &plugin.GRPCBackendPlugin{
			Factory: mock.Factory,
			Logger:  log.NewNullLogger(),
		},
	}
	client, _ := gplugin.TestPluginGRPCConn(t, false, pluginMap)
	defer client.Close()

	raw, err := client.Dispense(plugin.BackendPluginName)
	require.NoError(t, err)
	backend, ok := raw.(logical.Backend)
	require.True(t, ok, "dispensed plugin must satisfy logical.Backend (BackendServer contract)")

	storage := &logical.InmemStorage{}

	// Setup
	err = backend.Setup(context.Background(), &logical.BackendConfig{
		Logger: logging.NewVaultLogger(log.Debug),
		System: &logical.StaticSystemView{
			DefaultLeaseTTLVal: 300 * time.Second,
			MaxLeaseTTLVal:     1800 * time.Second,
		},
		StorageView: storage,
	})
	require.NoError(t, err, "Setup")

	// Type
	require.Equal(t, logical.TypeLogical, backend.Type(), "Type")

	// SpecialPaths
	paths := backend.SpecialPaths()
	require.NotNil(t, paths, "SpecialPaths")

	// Initialize
	err = backend.Initialize(context.Background(), &logical.InitializationRequest{Storage: storage})
	require.NoError(t, err, "Initialize")

	// HandleRequest
	resp, err := backend.HandleRequest(context.Background(), &logical.Request{
		Operation: logical.CreateOperation,
		Storage:   storage,
		Path:      "kv/foo",
		Data:      map[string]interface{}{"value": "bar"},
	})
	require.NoError(t, err, "HandleRequest")
	require.Equal(t, "bar", resp.Data["value"], "HandleRequest")

	// HandleExistenceCheck
	found, exists, err := backend.HandleExistenceCheck(context.Background(), &logical.Request{
		Operation: logical.CreateOperation,
		Storage:   storage,
		Path:      "kv/bar",
		Data:      map[string]interface{}{"value": "baz"},
	})
	require.NoError(t, err, "HandleExistenceCheck")
	require.True(t, found, "HandleExistenceCheck should report a check exists for kv/*")
	require.False(t, exists, "kv/bar was never written, so it should not exist yet")

	// InvalidateKey - must be callable without error/panic.
	require.NotPanics(t, func() { backend.InvalidateKey(context.Background(), "internal") }, "InvalidateKey")

	// Cleanup - must be callable without error/panic.
	require.NotPanics(t, func() { backend.Cleanup(context.Background()) }, "Cleanup")
}

// testRouterMountContract implements AC6 / implementation_steps #7. It
// exercises vault/router.go's Mount function indirectly through the live
// sys/mounts API (mounting through the real Core.mount -> Router.Mount
// path, rather than constructing a *Router by hand, since MountEntry
// construction and accessor assignment are Core-internal and unexported):
//   - protectedMounts: attempting to remount "sys/" (a protected path) must
//     fail, proving Router.Mount's caller-side protection is intact.
//   - singletonMounts: attempting to mount a second "system"-typed backend
//     must fail, proving singleton-type enforcement is intact.
//   - accessor generation: a fresh mount's accessor must match the stable
//     "<type>_<8 lowercase hex>" format vault/mount.go's
//     generateMountAccessor produces.
func testRouterMountContract(t *testing.T, client *api.Client) {
	t.Run("protected_mount_cannot_be_remounted", func(t *testing.T) {
		err := client.Sys().Remount("sys/", "sys-moved/")
		require.Error(t, err, "remounting the protected sys/ mount must fail")
	})

	t.Run("singleton_mount_type_rejected_at_new_path", func(t *testing.T) {
		err := client.Sys().Mount("second-system/", &api.MountInput{Type: "system"})
		require.Error(t, err, "mounting a second singleton-typed (system) backend must fail")
	})

	t.Run("accessor_generation_is_stable", func(t *testing.T) {
		mountPath := "wo040-router-contract/"
		require.NoError(t, client.Sys().Mount(mountPath, &api.MountInput{Type: "kv"}))
		defer client.Sys().Unmount(mountPath)

		mounts, err := client.Sys().ListMounts()
		require.NoError(t, err)
		entry, ok := mounts[mountPath]
		require.True(t, ok, "newly mounted %s must appear in sys/mounts", mountPath)
		require.Regexp(t, `^kv_[0-9a-f]{8}$`, entry.Accessor,
			"accessor for a kv mount must match vault/mount.go generateMountAccessor's <type>_<8-hex> format, got %q", entry.Accessor)
	})
}

// testJSONLimits implements AC7 / implementation_steps #8: send requests
// exceeding each JSON DoS-prevention limit and assert Vault rejects them
// rather than accepting an unbounded payload.
//
// AC7's literal wording expects "400 or 413 rejection". The suite instead
// asserts the status codes actually observed against the current codebase
// (documented per-case below), per testing_strategy's requirement that this
// story "establish a passing baseline on the current codebase" - not the
// codebase we might wish existed. Where the observed code differs from
// AC7's wording, this is noted as a real, pre-existing gap for a future
// hardening story, not silently reconciled.
func testJSONLimits(t *testing.T, client *api.Client, snap *contractSnapshot) {
	limits := snap.JSONDoSLimits
	require.Positive(t, limits.CustomMaxJSONDepth)
	require.Positive(t, limits.CustomMaxJSONStringValueLength)
	require.Positive(t, limits.CustomMaxJSONObjectEntryCount)
	require.Positive(t, limits.CustomMaxJSONArrayElementCount)
	require.Positive(t, limits.CustomMaxJSONToken)
	require.Positive(t, limits.DefaultMaxTokenHeaderSize)

	post := func(t *testing.T, path string, body []byte, extraHeaders map[string]string) *api.Response {
		req := client.NewRequest(http.MethodPost, path)
		req.BodyBytes = body
		for k, v := range extraHeaders {
			req.Headers.Set(k, v)
		}
		resp, err := client.RawRequestWithContext(context.Background(), req)
		if err != nil {
			respErr, ok := err.(*api.ResponseError)
			require.True(t, ok, "expected an *api.ResponseError for a rejected oversized request, got: %v", err)
			return &api.Response{Response: &http.Response{StatusCode: respErr.StatusCode}}
		}
		return resp
	}

	// wrapJSONLimitsHandler's error path (http/util.go's
	// jsonLimitsValidation) always responds 500 on any jsonutil violation
	// (depth/string/object/array/token) - it does not distinguish DoS
	// limit errors from other decode errors with a 400/413. This is the
	// observed current behavior these four subtests assert.
	t.Run("depth", func(t *testing.T) {
		body := deeplyNestedJSON(int(limits.CustomMaxJSONDepth) + 5)
		resp := post(t, "/v1/sys/quotas/rate-limit/wo040-json-limit-depth", body, nil)
		require.Equal(t, http.StatusInternalServerError, resp.StatusCode,
			"exceeding CustomMaxJSONDepth (%d) should be rejected (observed: 500 from jsonLimitsValidation)", limits.CustomMaxJSONDepth)
	})

	t.Run("string_value_length", func(t *testing.T) {
		big := strings.Repeat("a", int(limits.CustomMaxJSONStringValueLength)+16)
		body := []byte(fmt.Sprintf(`{"path":"auth/approle","rate":5,"note":%q}`, big))
		resp := post(t, "/v1/sys/quotas/rate-limit/wo040-json-limit-string", body, nil)
		require.Equal(t, http.StatusInternalServerError, resp.StatusCode,
			"exceeding CustomMaxJSONStringValueLength (%d) should be rejected (observed: 500)", limits.CustomMaxJSONStringValueLength)
	})

	t.Run("object_entry_count", func(t *testing.T) {
		body := wideJSONObject(int(limits.CustomMaxJSONObjectEntryCount) + 10)
		resp := post(t, "/v1/sys/quotas/rate-limit/wo040-json-limit-object", body, nil)
		require.Equal(t, http.StatusInternalServerError, resp.StatusCode,
			"exceeding CustomMaxJSONObjectEntryCount (%d) should be rejected (observed: 500)", limits.CustomMaxJSONObjectEntryCount)
	})

	t.Run("array_element_count_and_token_count", func(t *testing.T) {
		// Deliberately also exceeds CustomMaxJSONToken: constructing a
		// payload that trips MaxTokens (500,000) without also tripping the
		// 10,000-element array/object caps first is impractical (every
		// element/entry contributes at minimum ~2-4 tokens), so this case
		// documents that array-element-count and token-count are verified
		// together rather than claiming a token-count-only isolation this
		// payload shape cannot achieve.
		body := longJSONArray(int(limits.CustomMaxJSONArrayElementCount) + 10)
		resp := post(t, "/v1/sys/quotas/rate-limit/wo040-json-limit-array", body, nil)
		require.Equal(t, http.StatusInternalServerError, resp.StatusCode,
			"exceeding CustomMaxJSONArrayElementCount (%d) should be rejected (observed: 500)", limits.CustomMaxJSONArrayElementCount)
	})

	t.Run("token_header_size", func(t *testing.T) {
		// wrapTokenHeaderSizeHandler is the one limit that *does* return a
		// distinct, purpose-built status: 431 Request Header Fields Too
		// Large (http/util.go respondError(w, http.StatusRequestHeaderFieldsTooLarge, ...)).
		oversized := strings.Repeat("a", int(limits.DefaultMaxTokenHeaderSize)+16)
		resp := post(t, "/v1/sys/health", []byte(`{}`), map[string]string{"Authorization": "Bearer " + oversized})
		require.Equal(t, http.StatusRequestHeaderFieldsTooLarge, resp.StatusCode,
			"a token header exceeding DefaultMaxTokenHeaderSize (%d) must be rejected with 431, got %d", limits.DefaultMaxTokenHeaderSize, resp.StatusCode)
	})
}

// --- helpers ---

func pathTestName(path string) string {
	name := strings.TrimPrefix(path, "/")
	name = strings.ReplaceAll(name, "/", "_")
	if name == "" {
		name = "root"
	}
	return name
}

func representativeMethod(methods []string) string {
	for _, m := range methods {
		if m == http.MethodGet {
			return m
		}
	}
	if len(methods) > 0 {
		m := methods[0]
		if m == "LIST" || m == "RECOVER" {
			return http.MethodGet
		}
		return m
	}
	return http.MethodGet
}

func statusFromResponseOrError(t *testing.T, resp *api.Response, err error) int {
	if err == nil {
		require.NotNil(t, resp)
		return resp.StatusCode
	}
	if respErr, ok := err.(*api.ResponseError); ok {
		return respErr.StatusCode
	}
	t.Fatalf("unexpected transport-level error (not an HTTP response): %v", err)
	return 0
}

func deeplyNestedJSON(depth int) []byte {
	var buf bytes.Buffer
	buf.WriteString(`{"path":"auth/approle","rate":5,"nested":`)
	for i := 0; i < depth; i++ {
		buf.WriteString(`{"n":`)
	}
	buf.WriteString("true")
	for i := 0; i < depth; i++ {
		buf.WriteString("}")
	}
	buf.WriteString("}")
	return buf.Bytes()
}

func wideJSONObject(entries int) []byte {
	var buf bytes.Buffer
	buf.WriteString(`{"path":"auth/approle","rate":5,"wide":{`)
	for i := 0; i < entries; i++ {
		if i > 0 {
			buf.WriteByte(',')
		}
		buf.WriteString(`"k`)
		buf.WriteString(strconv.Itoa(i))
		buf.WriteString(`":1`)
	}
	buf.WriteString("}}")
	return buf.Bytes()
}

func longJSONArray(elements int) []byte {
	var buf bytes.Buffer
	buf.WriteString(`{"path":"auth/approle","rate":5,"items":[`)
	for i := 0; i < elements; i++ {
		if i > 0 {
			buf.WriteByte(',')
		}
		buf.WriteByte('1')
	}
	buf.WriteString("]}")
	return buf.Bytes()
}
